export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  const t = time;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedHeight = launchSpeed * t - (gravity * t * t) / 2;
  const tossedAcceleration = -gravity;

  const dropHeld = t < apexTime;
  const dropHeight = dropHeld ? apexHeight : tossedHeight;
  const dropVelocity = dropHeld ? 0 : -gravity * (t - apexTime);
  const dropAcceleration = dropHeld ? 0 : -gravity;

  let tossState = "At launch";
  if (t > 0.05 && t < apexTime - 0.05) tossState = "Rising";
  else if (Math.abs(t - apexTime) <= 0.05) tossState = "At the top";
  else if (t > apexTime + 0.05 && tossedHeight > 0) tossState = "Falling";
  else if (tossedHeight <= 0 && t > apexTime) tossState = "At launch height";

  let dropState = "Held in place";
  if (!dropHeld && t - apexTime < 0.05) dropState = "Just released";
  else if (!dropHeld && dropHeight > 0) dropState = "Falling together";
  else if (dropHeight <= 0 && !dropHeld) dropState = "At launch height";

  const maxH = 2.2;
  const mapY = (h) => 360 - (h / maxH) * 260;

  const tossY = mapY(Math.max(0, Math.min(maxH, tossedHeight)));
  const dropY = mapY(Math.max(0, Math.min(maxH, dropHeight)));

  const objects = [];

  objects.push(...sdk.panel({ x: 40, y: 50, w: 260, h: 320, title: "Toss lane", state: tossState, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 340, y: 50, w: 260, h: 320, title: "Drop lane", state: dropState, id: "lane.drop" }));

  objects.push(sdk.circle("ball.toss", 170, tossY, 28, { role: "output" }));
  objects.push(sdk.circle("ball.drop", 470, dropY, 28, { role: "output" }));

  objects.push(sdk.gate("gate", 470, mapY(apexHeight), { open: !dropHeld, w: 40, label: "Apex gate" }));

  objects.push(...sdk.vector("vec.v.toss", { x: 140, y: tossY }, { value: tossedVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: 200, y: tossY }, { value: tossedAcceleration, direction: "up" }, { scale: 10, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: 440, y: dropY }, { value: dropVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: 500, y: dropY }, { value: dropAcceleration, direction: "up" }, { scale: 10, label: "a" }));

  objects.push(...sdk.callout(215, tossY - 20, [
    "v: " + sdk.format(tossedVelocity, 2) + " m/s",
    "a: " + sdk.format(tossedAcceleration, 1) + " m/s^2"
  ], { id: "callout.toss" }));

  objects.push(...sdk.callout(515, dropY - 20, [
    "v: " + sdk.format(dropVelocity, 2) + " m/s",
    "a: " + sdk.format(dropAcceleration, 1) + " m/s^2"
  ], { id: "callout.drop" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
